'use strict';
const path=require('path');
if(process.env.LEADGEN_TEST_MODE!=='1')require('dotenv').config({path:path.resolve(__dirname,'../.env'),quiet:true});
const store=require('./store');
let ready=false;
function ensure(){if(ready)return;require('./migrate').migrate();require('./auth').setup();if(!process.env.ENCRYPTION_KEY){const fs=require('fs');const keyFile=path.join(store.dataDir,'encryption.key');if(!fs.existsSync(keyFile))fs.writeFileSync(keyFile,require('crypto').randomBytes(32).toString('hex'),{mode:0o600,flag:'wx'});process.env.ENCRYPTION_KEY=fs.readFileSync(keyFile,'utf8').trim();}if(!store.connection().prepare("SELECT 1 FROM documents WHERE name='queries'").get()){const fs=require('fs');const file=path.join(store.root,'search_queries.json');const source=fs.existsSync(file)?JSON.parse(fs.readFileSync(file,'utf8')):{queries:[],metadata:{}};const queries={queries:[...new Set((source.queries||[]).map(q=>typeof q==='string'?q:q.query).filter(Boolean))],metadata:source.metadata||{}};store.write('queries',queries);fs.writeFileSync(path.join(store.dataDir,'search_queries.json'),JSON.stringify(queries));}if(!store.connection().prepare("SELECT 1 FROM documents WHERE name='fixtureHashes'").get()){const fs=require('fs');const file=path.join(store.root,'ecommerce_store_leads.csv');let hashes=[];if(fs.existsSync(file)){const rows=require('./csv').parseCsv(fs.readFileSync(file,'utf8'));const index=rows[0]?.findIndex(h=>h.trim().toLowerCase()==='email');if(index>=0)hashes=[...new Set(rows.slice(1).map(r=>require('crypto').createHash('sha256').update((r[index]||'').toLowerCase().trim()).digest('hex')))];}store.write('fixtureHashes',hashes);}const migration=store.read('migration');if(migration.credentialSchema!==1){store.transaction(()=>{const settings=store.read('settings');settings.accounts=(settings.accounts||[]).map(a=>{const value={};for(const k of ['id','firstName','lastName','senderName','signature','smtpHost','smtpPort','imapHost','imapPort','dkimSelector','disabled'])if(k in a)value[k]=a[k];value.email=a.email||a.user;const password=a.password||a.pass;if(password)value.password=require('../cryptoUtils').isEncrypted(password)?password:require('../cryptoUtils').encrypt(password);return value;});store.write('settings',settings);store.write('migration',{...migration,credentialSchema:1});});}const marker=store.read('migration');if(marker.targetingSchema!==1){store.transaction(()=>{const d=store.read('leads');let excluded=0;for(const b of Object.values(d.businesses)){b.outreachExcludedReason=require('./targeting').exclusion(b);if(b.outreachExcludedReason)excluded++;}store.write('leads',d);store.write('migration',{...store.read('migration'),targetingSchema:1});store.record('targeting_policy_migrated',{businesses:Object.keys(d.businesses).length,excluded,maxEmployees:250,ownerEvidenceRequired:true});});}ready=true;}
module.exports={ensure};
